contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the recipient and amount; these are general inputs and the rule must hold for all
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient in the admissible domain (any address allowed, including zero)
        // record proposalCount before
        uint before = c.proposalCount();

        // call newGrantProposal as the fuzzed caller
        // use vm.prank to simulate msg.sender variability
        vm.prank(recipient);
        c.newGrantProposal(recipient, amount);

        // After call, reference should always have incremented by 1 (mutant that cancels increment will fail for some inputs)
        uint after = c.proposalCount();

        // Single assertion mandated: this checks the universal property (reference satisfies for all inputs)
        assertTrue(after == before + 1);
    }
