contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient wide but not zero-address to ensure proposals with a non-zero recipient
        // allow zero as well; no tight constraints so fuzzer can find failing cases
        uint before = c.proposalCount();
        // call newGrantProposal from a fuzzed sender to reflect typical use
        vm.prank(address(uint160(uint(keccak256(abi.encodePacked(recipient, amount, block.timestamp))))));
        c.newGrantProposal(recipient, amount);
        uint after = c.proposalCount();
        // General rule: after == before + 1 for the correct contract; the mutant that reverts the increment may break this
        assertTrue(after == before + 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        // keep addresses non-zero to be within typical domain but allow zero too
        vm.prank(caller);
        uint256 before = c.proposalCount();
        // call newGrantProposal as the fuzzed caller
        // we catch reverts to observe behavior but function does not revert in reference
        bool ok;
        try c.newGrantProposal(recipient, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 after = c.proposalCount();
        // General rule: reference always increments proposalCount by exactly 1.
        // We assert that after == before + 1. This holds for the reference for all inputs
        // and is violated by the mutant for some inputs (it may leave proposalCount unchanged).
        assertTrue(ok && after == before + 1);
    }
}

