pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing the recipient and amount; recipient is an address parameter which the fuzzer will supply
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient non-zero to be admissible but allow zero as well; wide domain
        // record before
        uint256 before = c.proposalCount();

        // call newGrantProposal as the fuzzed recipient (caller may be any EOA)
        // use vm.prank to simulate the call from recipient (but caller identity does not affect reference behavior)
        vm.prank(recipient);
        c.newGrantProposal(recipient, amount);

        // record after
        uint256 after = c.proposalCount();

        // General rule: the correct contract increases proposalCount by exactly 1 on each newGrantProposal call
        // The mutant that decrements immediately can break this, so assert the invariant
        assertTrue(after == before + 1);
    }
}
